def refund(balance_cents, requested_cents):
    if type(balance_cents) is not int or type(requested_cents) is not int:
        raise ValueError("integer cents required")
    if balance_cents < 0 or requested_cents < 0 or requested_cents > balance_cents:
        raise ValueError("invalid amount")
    return balance_cents - requested_cents

import unittest
from refund import refund
class RefundTests(unittest.TestCase):
    def test_valid(self):
        for a,b,c in [(100,30,70),(100,0,100),(100,100,0)]: self.assertEqual(refund(a,b),c)
    def test_invalid(self):
        for a,b in [(1,2),(-1,0),(1,-1),(1.0,0),(True,0)]:
            with self.assertRaises(ValueError): refund(a,b)

import unittest
from coupon import payable
class CouponTests(unittest.TestCase):
    def test_boundary(self):
        for cents,want in [(9999,9999),(10000,9000),(10001,9001)]:
            with self.subTest(cents=cents): self.assertEqual(payable(cents),want)

